<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('clinical.write');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$patientId=(int)($_GET['patient_id']??$_POST['patient_id']??0);$st=db()->prepare("SELECT * FROM patients WHERE id=:id AND tenant_id=:t");$st->execute(['id'=>$patientId,'t'=>$user['tenant_id']]);$patient=$st->fetch();if(!$patient||!\App\Core\Rbac::canViewPatientClinical($user,$patient)){http_response_code(403);require APP_ROOT.'/app/views/403.php';exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$content=['demanda'=>trim($_POST['demanda']??''),'historico'=>trim($_POST['historico']??''),'contexto'=>trim($_POST['contexto']??''),'saude'=>trim($_POST['saude']??''),'rede_apoio'=>trim($_POST['rede_apoio']??''),'objetivos'=>trim($_POST['objetivos']??'')];if(!$content['demanda'])$error='Descreva a demanda inicial.';else{$status=$user['role_slug']==='supervised'?'pending_approval':'draft';$sup=$user['role_slug']==='supervised'?(int)($user['supervisor_id']??0):null;$st=db()->prepare("INSERT INTO clinical_records(tenant_id,patient_id,professional_id,supervisor_id,record_type,content_enc,status,created_at,updated_at)VALUES(:t,:p,:u,:s,'anamnesis',:c,:st,NOW(),NOW())");$st->execute(['t'=>$user['tenant_id'],'p'=>$patientId,'u'=>$user['id'],'s'=>$sup?:null,'c'=>\App\Core\Crypto::encrypt($content),'st'=>$status]);$id=(int)db()->lastInsertId();audit('clinical.anamnesis_create','clinical_record',$id,['patient_id'=>$patientId]);redirect('clinical/view.php?id='.$id);}}layout('Anamnese',function()use($patient,$error){?><div class="page-head"><div><span class="eyebrow">Anamnese</span><h1 data-private><?=e($patient['name'])?></h1><p>Modelo estruturado, editável pelo profissional.</p></div></div><form method="post" class="card form-grid"><?=csrf_field()?><input type="hidden" name="patient_id" value="<?=$patient['id']?>"><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif?><?php foreach(['demanda'=>'Descrição da demanda / motivo da procura','historico'=>'Histórico relevante','contexto'=>'Contexto familiar, social e ocupacional','saude'=>'Saúde, medicações e acompanhamentos relatados','rede_apoio'=>'Rede de apoio','objetivos'=>'Objetivos terapêuticos iniciais'] as $k=>$label):?><div class="field"><label><?=e($label)?></label><textarea name="<?=$k?>"></textarea></div><?php endforeach?><button class="button">Salvar anamnese</button></form><?php },['active'=>'clinical']);
